[222] = { en = "Worgen in the Woods", tier = 2,
  t = "Worgen in de bossen",
  d = "Wat je eerder hebt gedaan, heeft me ervan overtuigd dat je klaar bent voor de sterkste worgen die de bossen onveilig maken.$b$bVan de worgen die zich hier gevestigd hebben, zijn de Vile Fangs en de Tainted Ones het gevaarlijkst gebleken. Ze wonen nu bij een paar grotten en in de mijn in het zuiden.$b$bVan ver weg kun je zelfs het licht van hun kampvuren zien...",
  o = "Dood 8 Nightbane Vile Fang en 8 Nightbane Tainted One worgen voor Calor in Darkshire.",
