[223] = { en = "Worgen in the Woods", tier = 2,
  t = "Worgen in de bossen",
  d = "Alsjeblieft, $n. Breng dit bericht naar Master Carevin.$b$b<Hij haalt snel een stuk verbleekt perkament tevoorschijn en geeft het aan je.>$b$bNog een paar mensen zoals jij, en we zijn met meer dan de Night Watch! Misschien kunnen we dan het werk afmaken dat wij, met z'n weinigen, nu doen.",
  o = "Breng Calor's note naar Jonathan Carevin.",
  p = "Ja, wat is er? Maak het kort, ik heb dringende zaken te regelen.",
  c = "Sorry voor mijn koude ontvangst, $N. Maar zoals je vast wel ziet, ben ik een heel drukke man. Ik zie dat je indruk hebt gemaakt op Calor -- en geloof me, dat is niet niks -- en dat hij je heeft aanbevolen.$b$bEr lopen hier louche types rond, $N, en we kunnen de hulp gebruiken van iedereen die zich heeft bewezen. We vechten tegen demonen, de ondoden en iedereen die hen helpt. Wees waakzaam, wees voorzichtig, en vertrouw niemand die onze zaak niet wil helpen.$b$bGlorie onder het Licht.",
  g = { {"verbleekt", "faded (verbleken)"}, {"perkament", "parchment"}, {"tevoorschijn", "out (into view)"}, {"met z'n weinigen", "the few of us"}, {"dringende zaken", "pressing matters"}, {"ontvangst", "reception"}, {"indruk hebt gemaakt", "have impressed (indruk maken)"}, {"dat is niet niks", "that is no small feat"}, {"aanbevolen", "recommended (aanbevelen)"}, {"louche", "shady, unsavory"}, {"zich heeft bewezen", "has proven themselves (zich bewijzen)"}, {"waakzaam", "vigilant"}, {"zaak", "cause"} },
},

[55] = { en = "Morbent Fel", tier = 2,
  t = "Morbent Fel",
  d = "Morbent Fel verstopt zich in zijn schuilplaats: het huis boven op de heuvel in het oosten, dat uitkijkt over de begraafplaats van Raven Hill. Zijn tijd in dit land is bijna voorbij...$B$BGebruik Morbent's Bane tegen hem. Daarmee werkt zijn beschermende magie niet meer.$B$BDood hem. Dood hem, en red ons van zijn kwaad. Wees het instrument van mijn wraak, en een held van Duskwood!",
  o = "Gebruik Morbent's Bane op Morbent Fel, dood Morbent Fel en breng Morbent's Bane daarna terug naar Sven in zijn kamp.",
  p = "Is Morbent Fel verslagen?!",
  c = "Morbent Fel is verslagen. De duistere ruiters zijn nog vrij, maar een klein deel van waar ik tegen alle hoop in op had gehoopt, is uitgekomen.$b$bJe hebt het onmogelijke gedaan. Je daden zullen voor altijd voortleven in de legendes van Duskwood.$b$bGa, $N. En misschien brengt het lot je ooit bij me terug...",
  g = { {"schuilplaats", "hiding place, lair"}, {"uitkijkt over", "overlooks (uitkijken over)"}, {"begraafplaats", "cemetery"}, {"beschermende", "protective"}, {"kwaad", "evil, wickedness"}, {"wraak", "revenge"}, {"verslagen", "defeated (verslaan)"}, {"ruiters", "riders (ruiter)"}, {"tegen alle hoop in", "beyond hope"}, {"is uitgekomen", "has come true (uitkomen)"}, {"daden", "deeds (daad)"}, {"voortleven", "to live on"}, {"het lot", "fate"} },
},

[505] = { en = "Syndicate Assassins", tier = 2,
  t = "Huurmoordenaars van het Syndicate",
  d = "Ik ben de nieuwe magistraat van Southshore. Ik ben kort geleden aangesteld, na de moord op de vorige magistraat. De moordenaars zijn nooit gevonden, maar door ons onderzoek weten we bijna zeker dat ze zijn ingehuurd door het Syndicate. Dat is een groep dieven onder leiding van schurkachtige edelen uit het gevallen koninkrijk Alterac.$B$BHet Syndicate heeft een kamp ten noorden van Tarren Mill, dat door de Horde bezet is. Onze laatste aanwijzingen leidden naar dat kamp. Dood de leden van het Syndicate die je daar vindt.",
  o = "Dood 12 Syndicate Footpads en 8 Syndicate Thieves en ga daarna terug naar Magistrate Henry Maleb in Southshore.",
  p = "Je hebt die boeven van het Syndicate gedood, neem ik aan?",
  c = "Dank je, $N. Misschien sluipen ze hier nog rond, maar we hopen dat een paar van de dieven en straatrovers die je hebt gedood, verantwoordelijk waren voor de dood van de vorige magistraat. Maar ook als dat niet zo is: het Syndicate is een vloek voor dit land en een smet op het menselijk ras.$B$BSouthshore is blij met hun dood.",
  g = { {"huurmoordenaars", "assassins (huurmoordenaar)"}, {"magistraat", "magistrate"}, {"aangesteld", "appointed, assigned (aanstellen)"}, {"onderzoek", "investigation"}, {"ingehuurd", "hired (inhuren)"}, {"onder leiding van", "led by"}, {"schurkachtige", "villainous (schurkachtig)"}, {"edelen", "nobles (edele)"}, {"bezet", "occupied"}, {"aanwijzingen", "clues (aanwijzing)"}, {"boeven", "thugs, crooks (boef)"}, {"sluipen", "to lurk, sneak"}, {"straatrovers", "footpads (straatrover)"}, {"smet", "stain"} },
},

[510] = { en = "Foreboding Plans", tier = 2,
  t = "Onheilspellende plannen",
  d = "Tussen deze documenten zit een lijst met gevraagde voorraden. Daarop staan gewone spullen (eten, wapens, kleding), maar ook bijzondere uitrusting (maskers, olie, gif).$B$BMaar het opvallendste is hoe dringend het verzoek is. Deze voorraden waren snel nodig voor wat het document een \"belangrijke missie tegen Southshore\" noemt.",
  o = "Breng de Foreboding Plans naar Magistrate Maleb in Southshore.",
  p = "$N, je ziet er bezorgd uit. Wil je me iets vertellen?",
  c = "<Maleb leest de documenten.>$B$BDit is heel verontrustend, $N. Uit de informatie in deze documenten, en uit wat het Syndicate eerder heeft gedaan, moeten we aannemen dat die bende moordenaars Southshore de oorlog heeft verklaard.",
  g = { {"onheilspellende", "foreboding (onheilspellend)"}, {"voorraden", "supplies (voorraad)"}, {"uitrusting", "gear, equipment"}, {"opvallendste", "most notable (opvallend)"}, {"dringend", "urgent"}, {"verzoek", "request"}, {"bezorgd", "anxious, worried"}, {"verontrustend", "troubling"}, {"aannemen", "to assume"}, {"bende", "band, gang"}, {"de oorlog heeft verklaard", "has declared war"} },
