[514] = { en = "Letter to Stormpike", tier = 2,
  t = "Brief voor Stormpike",
  d = "Ik heb een collega in Ironforge die deze brief misschien kan ontcijferen. Ga naar de bibliotheek in de Hall of Explorers in Ironforge en praat met Prospector Stormpike. Zeg dat ik je stuur en laat hem de brief zien. Als iemand ten noorden van Blackrock Spire dit kan lezen, is hij het.",
