[525] = { en = "Further Mysteries", tier = 2,
  t = "Meer raadsels",
  d = "Ik heb de brief ontcijferd, maar ik weet niet wat ik ervan moet denken. Heb je dit gevonden bij dieven in de heuvels van Alterac? Heel vreemd...$B$BJe moet dit naar de magistraat van Southshore brengen. De brief is raadselachtig, maar zijn stad ligt het dichtst bij Alterac. Als er gevaar dreigt, moet hij het weten.",
  o = "Breng de Decrypted Letter naar Magistrate Maleb in Southshore.",
  p = "$N. Ben je weer door de heuvels en de bergen gereisd? Welk nieuws breng je?",
  c = "<Maleb leest de brief.>$B$BIs dit de vertaling van een brief die je in een kamp van het Syndicate hebt gevonden? Dit is niet geschreven door een dief, en zelfs niet door een edelman van Alterac.$B$BHet lijkt erop dat het Syndicate banden heeft met een andere macht. Ik huiver bij de gedachte wat dat zou kunnen zijn.",
