[98] = { en = "The Legend of Stalvan", tier = 2,
  t = "De legende van Stalvan",
  d = "Stalvan Mistmantle leidde een verdorven leven. Onschuldige slachtoffers stierven door zijn hand. Hij is ongetwijfeld schuldig aan talloze misdaden. Nu bedreigt die gek Darkshire. Alleen het Licht weet welke smerige daden hij van plan is. Ga naar zijn huisje net ten noorden van de stad, $c, en executeer Stalvan, voor eens en altijd.$b$bAls het gedaan is, ga dan naar Madame Eva en laat haar zijn familiering zien. Het was tenslotte haar voorgevoel dat tot deze gruwelijke ontdekking leidde. Maar dankzij haar is Darkshire veiliger.",
  o = "Dood Stalvan Mistmantle en laat Madame Eva zijn familiering zien.",
  p = "Ja, $N?",
  c = "Ik weet het, $N: Stalvan is dood. Ik voelde een golf van hoop door het besmette bos gaan. Duskwood is voor eens en altijd vrij van zijn bloeddorst. Mijn vreugde wordt wel getemperd door gedachten aan iedereen die slachtoffer werd van dat vreselijke beest. Toch ben je een dappere en slimme $c.",
  g = { {"verdorven", "depraved"}, {"slachtoffers", "victims (slachtoffer)"}, {"ongetwijfeld", "undoubtedly"}, {"schuldig", "guilty"}, {"talloze", "countless"}, {"misdaden", "crimes (misdaad)"}, {"smerige", "sordid, filthy (smerig)"}, {"executeer", "execute (executeren)"}, {"voor eens en altijd", "once and for all"}, {"voorgevoel", "premonition"}, {"gruwelijke", "gruesome (gruwelijk)"}, {"besmette", "tainted (besmet)"}, {"bloeddorst", "blood thirst"}, {"getemperd", "dampened, hampered (temperen)"} },
},

[225] = { en = "The Weathered Grave", tier = 2,
  t = "Het verweerde graf",
  d = "Op de verweerde grafsteen staat alleen:$b$bMORGAN LADIMORE$b$b<Als je beter kijkt, zie je dat de aarde op het graf kortgeleden is omgewoeld. Een flinke hoeveelheid aarde lijkt verplaatst te zijn...>",
  o = "Praat met Sirra Von'Indi in Darkshire.",
  c = "Morgan Ladimore?$b$bAh, ja, natuurlijk. Zijn verhaal was lang en treurig. Ik kende hem goed, voordat hij naar de oorlog vertrok. Maar toen heb ik hem voor het laatst gezien. Hij was een nobele en goede man, maar het is slecht met hem afgelopen.$b$bHier, ik moet hier iets hebben dat het verhaal beter kan vertellen dan mijn eigen herinneringen...",
  g = { {"verweerde", "weathered (verweerd)"}, {"grafsteen", "grave marker"}, {"kortgeleden", "recently"}, {"omgewoeld", "disturbed, dug up (omwoelen)"}, {"flinke hoeveelheid", "good amount"}, {"verplaatst", "displaced, moved (verplaatsen)"}, {"treurig", "sorrowful, sad"}, {"nobele", "noble (nobel)"}, {"het is slecht met hem afgelopen", "he suffered a bad end"}, {"herinneringen", "recollections, memories (herinnering)"} },
},

[227] = { en = "Morgan Ladimore", tier = 2,
  t = "Morgan Ladimore",
  d = "<Hij zoekt tussen de boekenplanken en pakt een in leer gebonden boek.>$b$bAls je meer wilt weten, kun je het Althea vragen. Zij heeft de laatste tijd de... problemen... met hem afgehandeld.",
  o = "Praat met Commander Althea Ebonlocke in Darkshire.",
  c = "Morgan Ladimore? Nooit van gehoord...$b$bO, je bedoelt Mor'Ladim! Je kent het verhaal zeker nog niet?$b$bNou, ik vertel je de korte versie. Een rondzwervende ondode die zichzelf Mor'Ladim noemt, zwerft door Duskwood. Voor zover wij weten, is het het ondode lichaam van Morgan Ladimore, die jij blijkbaar kent. Hij bezorgt ons allerlei problemen: hij valt Watchmen op patrouille aan en doodt mensen.$b$b<Ze bekijkt je van top tot teen.>$b$bJe lijkt me bekwaam genoeg. Misschien kun jij hem te ruste leggen.",
  g = { {"boekenplanken", "bookshelves (boekenplank)"}, {"in leer gebonden", "leatherbound"}, {"de laatste tijd", "of late, lately"}, {"afgehandeld", "handled, dealt with (afhandelen)"}, {"rondzwervende", "wandering (rondzwerven)"}, {"zwerft", "wanders (zwerven)"}, {"voor zover wij weten", "from what we've gathered"}, {"blijkbaar", "apparently"}, {"bezorgt", "causes (bezorgen)"}, {"van top tot teen", "from head to toe"}, {"bekwaam", "capable"}, {"te ruste leggen", "to lay to rest"} },
},

[228] = { en = "Mor'Ladim", tier = 2,
  t = "Mor'Ladim",
  d = "Volgens mijn verkenners zwerft Mor'Ladim door heel Duskwood. Hij volgt een vreemd, kronkelend pad over de begraafplaats. We hebben hem begraven voorbij het huis op de heuvel, weet je waar dat is?$b$bIk kan niets doen om je te helpen, maar ik wens je veel succes.",
  o = "Dood Mor'Ladim en breng zijn schedel daarna terug naar Commander Althea Ebonlocke in Darkshire.",
  p = "Ik neem het je niet kwalijk als je moeite met hem hebt, $N. We zijn een paar van onze sterkste Watchers kwijtgeraakt aan Mor'Ladim.",
  c = "Heb je hem gedood? Dat is niet niks, $N! Namens de mensen van Darkshire en de Night Watch dank ik je.$B$BAh... er is wel nog één kleine kwestie...",
  g = { {"verkenners", "scouts (verkenner)"}, {"kronkelend", "meandering, winding"}, {"begraafplaats", "cemetery"}, {"begraven", "buried (begraven)"}, {"schedel", "skull"}, {"ik neem het je niet kwalijk", "I don't blame you"}, {"kwijtgeraakt", "lost (kwijtraken)"}, {"namens", "on behalf of"}, {"kwestie", "matter, issue"} },
},

[229] = { en = "The Daughter Who Lived", tier = 2,
  t = "De dochter die nog leefde",
  d = "Ik had je dit eerder moeten vertellen...$b$bHoe zeg ik dit...$b$bMorgan dacht misschien dat zijn hele familie dood was. Maar in werkelijkheid is zijn dochter Sarah Ladimore nu een Watcher. Ze heeft het altijd moeilijk gehad met de... omstandigheden... rond de dood van haar vader. Misschien kun jij haar het nieuws gaan vertellen.",
  o = "Praat met Watcher Sarah Ladimore in Darkshire.",
  c = "Ja? Mijn vader...$B$B<Ze kijkt naar beneden.>$B$BIk wou... dat ik iets voor hem had kunnen doen... Had ik maar met hem gepraat voordat hij...",
  g = { {"in werkelijkheid", "in fact, in reality"}, {"het moeilijk gehad met", "been troubled by"}, {"omstandigheden", "circumstances (omstandigheid)"}, {"ik wou dat", "I wish"}, {"had ik maar", "if only I had"} },
},

[231] = { en = "A Daughter's Love", tier = 2,
  t = "De liefde van een dochter",
  d = "Hier, neem dit en leg het op zijn graf. Misschien... weet hij dan op de een of andere manier dat het goed met me gaat. En dat niemand van ons hem verantwoordelijk houdt voor wat er gebeurd is.$b$b<Ze heeft nu tranen in haar ogen. Ze schuift een ring van haar rechterhand en drukt hem in je handen.>$b$bEn... dank je, $n.",
  o = "Breng de ring van Sarah Ladimore naar het graf van Morgan Ladimore.",
  p = "Laat me met rust...",
  c = "<Een spookachtige stem klinkt op de wind...>$B$BIs dit...? Sarah? Zou ze nog leven? Het gewicht is van mijn schouders genomen...$B$B$N. Neem mijn zwaard, Archeus. Nu mijn ziel rust vindt, heb ik het niet meer nodig. Het is gesmeed om goed te doen. Ik heb bewezen dat ik het niet waard ben om het te dragen, maar misschien draag jij het Licht ermee verder.$B$BLys, mijn liefste...",
  g = { {"op de een of andere manier", "somehow"}, {"verantwoordelijk houdt", "holds responsible (verantwoordelijk houden)"}, {"tranen", "tears (traan)"}, {"schuift", "slides (schuiven)"}, {"drukt", "presses (drukken)"}, {"laat me met rust", "leave me be"}, {"spookachtige", "ghostly (spookachtig)"}, {"gewicht", "weight"}, {"ziel", "soul"}, {"gesmeed", "forged (smeden)"}, {"het niet waard", "unworthy of it"} },
},

[254] = { en = "Digging Through the Dirt", tier = 2,
  t = "Graven in de aarde",
  c = "Je graaft door de half losse aarde op het graf... en vindt de resten van een doodskist.$B$BIn de kist voel je het trillende gekras van vingers met klauwen en het knarsen van rotte tanden...$B$BOpen je de kist en haal je het Embalmer's Heart eruit?",
  g = { {"graaft", "dig (graven)"}, {"resten", "remains (rest)"}, {"doodskist", "coffin"}, {"trillende", "vibrating (trillen)"}, {"gekras", "scraping, scratching"}, {"klauwen", "claws (klauw)"}, {"knarsen", "gnashing"}, {"rotte", "rotten (rot)"} },
