[500] = { en = "Crushridge Bounty", tier = 3,
  t = "Premie op de Crushridge",
  d = "De Crushridge-ogers hebben een ogerheuvel gegraven in de Alterac Mountains, vlak bij de verwoeste stad Alterac. En volgens mijn verkenners hebben ze ook die ruïnes ingenomen.$B$BWe mogen niet toestaan dat ze het zich daarboven gemakkelijk maken. Als ze denken dat ze daar veilig zijn, trekken ze daarna naar beneden, de uitlopers van de bergen in. En dan staan ze recht voor onze deur!$B$BGa naar het noorden, naar de Alterac Mountains, en jaag op ogers. Breng me de Dirty Knucklebones die ze bij zich hebben, dan verdien je een mooie premie.",
  o = "Verzamel 9 Dirty Knucklebones van Crushridge-ogers in de Alterac Mountains. Breng ze naar Marshal Redpath in Southshore.",
  p = "$N, jaag je nog op ogers? Heb je de knokkels die je voor me moest verzamelen?",
  c = "Heel goed, $N. Je hebt vast een hele hoop ogers neergehakt om al deze knokkels te krijgen.$B$BDaarmee houden we ze wel van ons lijf. In elk geval voor een tijdje.",
  g = { {"premie", "bounty"}, {"ogers", "ogres (oger)"}, {"ogerheuvel", "ogre mound"}, {"verwoeste", "ruined (verwoest)"}, {"verkenners", "scouts (verkenner)"}, {"ruïnes", "ruins (ruïne)"}, {"ingenomen", "taken over (innemen)"}, {"toestaan", "to allow"}, {"het zich gemakkelijk maken", "to get comfortable, cozy"}, {"uitlopers", "foothills (uitloper)"}, {"knokkels", "knucklebones (knokkel)"}, {"neergehakt", "hacked down (neerhakken)"}, {"van ons lijf houden", "to keep at arm's length, out of our hair"} },
},

[512] = { en = "Noble Deaths", tier = 3,
  t = "Dode edelen",
  d = "Ik vrees dat de leiders van het Syndicate erop uit zijn om Southshore te vernietigen. We moeten deze leiders hard raken voordat hun plannen werkelijkheid worden.$B$BGa naar de ruïnes van Strahnbrad, in de Alterac Mountains in het noorden. We denken dat het Syndicate die plek als hoofdkwartier gebruikt.$B$BWe weten dat deze bende moordenaars geleid wordt door vroegere edelen van Alterac. Misschien vermommen ze zich als gewone agenten van het Syndicate, maar aan de zegelring die hij draagt, weet je dat je een edelman hebt gedood.$B$BBreng me die zegelringen.",
  o = "Breng 7 Alterac Signet Rings naar Magistrate Maleb in Southshore.",
  p = "Heb je op het Syndicate gejaagd? Heb je die ringen?",
  c = "Als we het Syndicate zijn edelen afnemen, kan het niet meer doortastend optreden. Dan is het niets meer dan een bende boeven.$B$BJe dient je Alliance goed, $N.",
  g = { {"vrees", "fear (vrezen)"}, {"erop uit zijn", "to be bent on"}, {"vernietigen", "to destroy, ruin"}, {"werkelijkheid worden", "to be realized, come true"}, {"hoofdkwartier", "headquarters"}, {"geleid", "run, led (leiden)"}, {"vroegere", "former (vroeger)"}, {"vermommen", "to disguise"}, {"zegelring", "signet ring"}, {"afnemen", "to strip of, take away"}, {"doortastend", "decisively"}, {"optreden", "to act"}, {"dient", "serve (dienen)"} },
},

[522] = { en = "Assassin's Contract", tier = 3,
  t = "Het contract van de huurmoordenaar",
  d = "Dit is een contract voor de moord op Magistrate Henry Maleb. Het is verzegeld en gestempeld met rode lak, met een opvallende zegelring.",
  o = "Breng het Assassin's Contract naar Magistrate Maleb in Southshore.",
  p = "Je bent buiten adem! Heb je iets te melden?",
