[504] = { en = "Crushridge Warmongers", tier = 3,
  t = "De Crushridge Warmongers",
  d = "Nu je de Crushridge-ogers hebt leren kennen, wil ik dat je ze echt een bloedneus slaat...$B$BGa naar de Ruins of Alterac en zoek de Crushridge Warmongers op. Ik wil dat je er flink wat van neerhaalt. Alleen zo leren die bruten dat ze uit de buurt van het gebied van de Alliance moeten blijven.",
  o = "Dood 15 Crushridge Warmongers en ga daarna terug naar Marshal Redpath in Southshore.",
