  c = "Heel goed. Hier is je beloning.$B$BEn toen je op die Warmongers jaagde, hoe zag de stad Alterac eruit? Hij is er slecht aan toe, denk ik. Ogers staan niet bekend om hun netheid.$B$BGelukkig helpt jouw werk om ze uit de buurt van Southshore te houden.",
  g = { {"ogers", "ogres (oger)"}, {"een bloedneus slaat", "bloody their noses (een bloedneus slaan)"}, {"flink wat", "a good number"}, {"neerhaalt", "cut down (neerhalen)"}, {"bruten", "brutes (bruut)"}, {"uit de buurt", "away, at a distance"}, {"gebied", "territory, area"}, {"opgeborgen", "stowed (opbergen)"}, {"beloning", "reward"}, {"er slecht aan toe", "in bad shape"}, {"staan niet bekend om", "are not known for"}, {"netheid", "cleanliness"} },
