[523] = { en = "Baron's Demise", tier = 3,
  t = "Het einde van de baron",
  d = "Het contract dat je hebt gevonden, is ondertekend door Baron Vardus. Hij is een edelman uit het vroegere koninkrijk Alterac, bekend om zijn kille hart en wrede gewoontes. Het verbaast me niet dat iemand als de baron hierachter zat.$B$BZoek deze man. Zoek hem en breng hem voor het gerecht. Hij moet ergens in een van de schuilplaatsen van het Syndicate zitten, misschien in de ruïnes van Strahnbrad, of misschien in het dal ten noorden daarvan.",
