},

[537] = { en = "Dark Council", tier = 3,
  t = "Duistere raad",
  d = "De brief die je me bracht, is geschreven door een wezen dat zichzelf Nagaz noemt, een lid van de Argus Wake. Ik weet niet wat die Argus Wake is, maar als ze samenwerken met het Syndicate, moeten ze een bedreiging zijn.$B$BIk wil dat je Nagaz vindt, en de Argus Shadow Mages die in die brief genoemd worden. Ik wil dat je ze vindt en doodt.$B$BZoek in de Uplands, waar het Syndicate het sterkst is. Dat gebied ligt ten noorden van Strahnbrad.$B$BMet een beetje geluk vind je daar deze gezanten van de Argus Wake.",
