[554] = { en = "Stormpike's Deciphering", tier = 3,
  t = "Stormpike ontcijfert",
  d = "Prospector Stormpike is een meester in het ontsleutelen en ontcijferen. Als je het perkament dat je gevonden hebt naar hem brengt, kan hij het met een beetje geluk begrijpen. Stormpike studeert nu in het hoofdkwartier van de Prospectors in Ironforge.$B$BEn als je hem ziet, zeg hem dan dat je met mij gepraat hebt. Ik heb hem de laatste tijd heel wat werk bezorgd.",
