},

[1395] = { en = "Supplies for Nethergarde", tier = 3,
  t = "Voorraden voor Nethergarde",
  d = "Deze krat met krachtstenen moet naar Nethergarde Keep, in de Blasted Lands. De stenen houden hun kracht niet lang vast, dus we kunnen ze niet met de volgende karavaan meesturen.$B$BJij moet ze brengen, en wel snel.$B$BBreng ze naar Quartermaster Lungertz in Nethergarde Keep. Om bij het fort te komen, reis je naar het oosten door Deadwind Pass, dan naar het oosten door de Swamp of Sorrows, en daarna naar het zuiden door de Blasted Lands.$B$BWees voorzichtig, $N. Je reist door gevaarlijke gebieden, maar je mag niet falen.",
